raw_text:
{
  "spans": [
    {
      "label": "QUOTE",
      "head": "འཁོར་བའི་བག་ཆགས་རྒྱ་ཆེ་འཐུག་པོ་ཡང་། །",
      "tail": "རང་སེམས་རྟོགས་པའི་སྐད་ཅིག་གཅིག་གིས་སེལ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་རིན་པོ་ཆེ་སྒམ་པོ་པའི་ཞལ་ནས།",
      "head": "གསང་སྔགས་ཀྱི་ལྟ་སྤྱོད་སྒོམ་གསུམ་གྱི་སྒོམ་གཤའ་མ་ཞིག་བྱེད་ན། ཆགས་པ་དང་ཡོན་ཏན་གྱིས་རློམ་པ་གཉིས་བདུད་དུ་ཆེ་བར་འདུག་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "འདུལ་བ་ནས།",
      "head": "ངེས་པར་འབྱུང་བའི་ཚུལ་ཁྲིམས་སྡུག་བསྔལ་སྤོང་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སློབ་དཔོན་ཆོས་མཆོག་གིས།",
      "head": "བདག་དགེ་སློང་གི་སྡོམ་པ་འདི་ལས་ཉེས་པ་ཕྲ་བའི་ཕྲ་བས་ཀྱང་མ་གོས་ན། ཤིང་སྐམ་པོ་འདི་ལ་མེ་ཏོག་སྐྱེ་བར་གྱུར་ཅིག །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཚུལ་ཁྲིམས་གཡག་རྔ་བཞིན་དུ་བསྲུང་བ་དང་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རང་གི་ལུས་བཞིན་བསླབ་པ་བསྲུང་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བྱང་ཆུབ་སེམས་དཔའི་སྡེ་སྣོད་ལས་",
      "head": "ཆོ་ག་ནི་ཉན་ཐོས་ཀྱི་སྡེ་སྣོད་ལ་ལྟོས་སོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མངོན་རྟོགས་རྒྱན་ལས།",
      "head": "སེམས་བསྐྱེད་པ་ནི་གཞན་དོན་ཕྱིར། ། ཡང་དག་རྫོགས་པའི་བྱང་ཆུབ་འདོད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "འཁོར་བ་ཐོག་མ་མེད་པའི་མདོ་ལས།",
      "head": "མ་ཡི་ཐུག་མཐའ་བརྒྱ་ཤུག་ཚིག་གུ་ཙམ། ། རིལ་བུར་བགྲངས་ཀྱང་ས་ཡིས་ལང་མི་འགྱུར། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཕ་རོལ་ཏུ་ཕྱིན་པ་ལས་",
      "head": "ཉན་ཐོས་ཀྱིས་འཇིག་རྟེན་གྱི་ཁམས་འདི་འདམ་བུའི་ཚལ་ལམ་འོད་མའི་ཚལ་ལྟར་གང་བར་གྱུར་པས་དེ་དག་གི་ཤེས་རབ་ཀྱི་ཕ་རོལ་ཏུ་ཕྱིན་པ་བསྐལ་པར་བསྒོམ་པ་བས། བྱང་ཆུབ་སེམས་དཔའ་གཅིག་གིས་སྐད་ཅིག་གིས་ཤེས་རབ་ཀྱི་ཕ་རོལ་ཏུ་ཕྱིན་པ་བསྒོམས་པ་བསོད་ནམས་ཆེའོ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སྡུད་པ་ལས།",
      "head": "མི་ཡིས་འཇིག་རྟེན་འབྱུང་པོའི་གདོན་དང་ནད་མང་བ། ། ཕན་དང་སྙིང་བརྩེར་ལྡན་པའི་བྱིན་གྱིས་བརླབས་ཀྱིས་ཞི། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སྤྱོད་འཇུག་ལས།",
      "head": "གང་གི་ཆོས་ཀྱི་གཙོ་བོ་མཆོག ། སེམས་ཀྱི་གསང་འདི་མ་ཤེས་ན། ། བདེ་ཐོབ་སྡུག་བསྔལ་གཞོམ་འདོད་ཀྱང་། ། དེ་དག་དོན་མེད་གྱི་ནར་འཁྱམས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སེམས་ཅན་ཐམས་ཅད་སེམས་གཅིག་སྟེ། ། འོད་གསལ་སྐྱེ་བ་མེད་པའི་དོན། ། ཉོན་མོངས་འཇོམས་པའི་དཔའ་བོ་སྟེ། ། དེས་ན་ཏིང་ངེ་འཛིན་ཞེས་བསྟན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ནམ་མཁའ་ལྟ་བུའི་མདོ་ལས།",
      "head": "བླ་མ་དམ་པའི་བདུད་རྩི་ཡིས། ། རང་སེམས་ནམ་མཁའ་ལྟ་བུར་རྟོགས། ། དེ་ཡི་དོན་ལ་མ་ཡེངས་པ། ། དེ་ནི་ཏིང་ངེ་འཛིན་ཞེས་བསྟན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གསང་འདུས་ལས།",
      "head": "སྲོག་ཆགས་བྱེ་བ་བསོད་ལྡན་ཞིང་། ། ཉིན་བཞིན་བྲམ་ཟེ་བསོད་པ་དང༌། ། མཚམས་མེད་ལྔ་པོ་བྱེད་པ་ཡང་། ། ཆོས་འདི་ལ་ནི་ཞུགས་གྱུར་ཅིང་། ། བླ་མ་ལ་གུས་ཡོད་གྱུར་ན། ། འགྲུབ་འགྱུར་འདི་ལ་ཐེ་ཚོམ་མེད། ། བླ་མ་ལ་གུས་མེད་གྱུར་ན། ། བསྒྲུབས་ཀྱང་འགྲུབ་པར་མི་འགྱུར་རོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དུས་འཁོར་ལས།",
      "head": "བསྐལ་པ་དུས་གསུམ་ཐམས་ཅད་དུ། ། དཀོན་མཆོག་གསུམ་པོ་མཆོད་པ་དང༌། ། སྲོག་ཆགས་བྱེ་བའི་ཚེ་སྐྱབས་ཀྱང་། ། ཚེ་འདིར་འབྲས་བུ་མི་འཐོབ་སྟེ། ། ཡོན་ཏན་རྒྱ་མཚོའི་བླ་མ་ལ། ། དང་བའི་ཡིད་ཀྱིས་མཉེས་བྱས་ན། ། མཆོག་དང་ཐུན་མོང་དངོས་གྲུབ་ནི། ། ཚེ་འདི་ཉིད་ལ་ཐོབ་པར་འགྱུར། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "མདོ་ལས།",
      "head": "ཇི་ལྟར་ཟས་སྐོམ་སྣ་ཚོགས་ཀྱིས། ། སྐྱེ་བོ་མང་པོ་མགུ་བྱེད་ཀྱང་། ། བདག་ཉིད་རྟོགས་ཏེ་ཤི་བ་ལྟར། ། མ་བསྒོམས་ཆོས་ཀྱང་དེ་བཞིན་ནོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སོ་སོར་ཐར་པ་ལས།",
      "head": "མང་དུ་ཐོས་པ་ནགས་ཀྱི་ནང་དག་ཏུ། ། ལང་ཚོ་ཡོལ་བ་རྣམས་ཀྱིས་གནས་པ་བདེ། །",
      "tail": ""
    }
  ]
}
